# Analyze each color grouping by finding bounding boxes and holes
def analyze_color_groups(grid):
    import collections
    visited = set()
    groups = collections.defaultdict(list)

    for color in range(1, 10):
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color and (r, c) not in visited:
                    group = []
                    to_visit = [(r, c)]
                    while to_visit:
                        curr = to_visit.pop()
                        if curr in visited or curr[0] >= len(grid) or curr[1] >= len(grid[0]):
                            continue
                        if grid[curr[0]][curr[1]] != color:
                            continue
                        visited.add(curr)
                        group.append(curr)
                        to_visit.extend([(curr[0]+1, curr[1]), (curr[0]-1, curr[1]), 
                                       (curr[0], curr[1]+1), (curr[0], curr[1]-1)])
                    groups[(color, len(group))].extend(group)

    return groups

groups = analyze_color_groups(grid)
for key, cells in groups.items():
    color = key[0]
    size = key[1]
    rows = [c[0] for c in cells]
    cols = [c[1] for c in cells]
    min_row, max_row = min(rows), max(rows)
    min_col, max_col = min(cols), max(cols)
    height = max_row - min_row + 1
    width = max_col - min_col + 1

    # Check for holes (empty cells within bounding box)
    holes = 0
    for pr in range(min_row, max_row + 1):
        for pc in range(min_col, max_col + 1):
            if grid[pr][pc] == 0:
